import type { Readable } from "node:stream";

export interface PutResult {
  sizeBytes: number;
  checksumSha256: string;
  /** First bytes of the object, used for content-type detection. */
  head: Buffer;
}

/**
 * Storage backend. Keys are opaque, generated by the platform, and never
 * derived from user-supplied filenames.
 */
export interface StorageDriver {
  readonly name: "local" | "s3";
  /**
   * Streams `body` into storage under `key`. Aborts (and leaves nothing behind)
   * if more than `maxBytes` arrive.
   */
  put(key: string, body: Readable | AsyncIterable<Uint8Array>, opts: { maxBytes: number }): Promise<PutResult>;
  get(key: string): Promise<Readable>;
  delete(key: string): Promise<void>;
  exists(key: string): Promise<boolean>;
  /** Health probe: can the backend be written to? */
  healthCheck(): Promise<void>;
}

export class UploadTooLargeError extends Error {
  constructor(readonly maxBytes: number) {
    super(`Upload exceeds ${maxBytes} bytes`);
  }
}
